print(f"-273.15C = {celsius_to_fahrenheit(-273.15)}F")

# Test invalid types
try:
    celsius_to_fahrenheit("0")
except TypeError as e:
    print(f"Caught expected TypeError for string: {e}")

try:
    celsius_to_fahrenheit(True)
except TypeError as e:
    print(f"Caught expected TypeError for bool: {e}")

# Test invalid values
try:
    celsius_to_fahrenheit(-273.16)
except ValueError as e:
    print(f"Caught expected ValueError for too low: {e}")

